const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const california = ee.FeatureCollection("USGS/FED/US_STATES")
    .filter(ee.Filter.eq('STATE_NAME', 'California'))
    .first()
    .geometry();

  const startDate2017 = '2017-04-01';
  const endDate2017 = '2017-04-30';
  const startDate2012 = '2012-08-01';
  const endDate2012 = '2012-08-31';

  const bandName = 'SoilMoi0_10cm_inst'; // Soil moisture content in 0-10 cm layer

  // 2. Data Acquisition & Check
  const gldas = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H');

  const collection2017 = gldas.filterDate(startDate2017, endDate2017)
    .select(bandName);
  const collection2012 = gldas.filterDate(startDate2012, endDate2012)
    .select(bandName);

  const size2017 = await collection2017.size().getInfo();
  const size2012 = await collection2012.size().getInfo();

  if (size2017 === 0 || size2012 === 0) {
    console.log(`2017 Images: ${size2017}`);
    console.log(`2012 Images: ${size2012}`);
    console.log("C1"); // Empty Collection
    return;
  }

  // Calculate mean image for each period
  const meanImage2017 = collection2017.mean();
  const meanImage2012 = collection2012.mean();

  const scale = 3000; // Use a coarse scale for faster computation

  // 3. Processing & Calculation
  const getStats = async (image, geometry, year) => {
    const reduced = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Specify CRS for consistency
      tileScale: 4
    });

    const meanVal = await reduced.get(bandName).getInfo();
    const pixelCount = await reduced.get(bandName + '_count').getInfo();

    return { meanVal, pixelCount };
  };

  const stats2017 = await getStats(meanImage2017, california, '2017');
  const stats2012 = await getStats(meanImage2012, california, '2012');

  const mean_sm_2017 = stats2017.meanVal;
  const pixel_count_2017 = stats2017.pixelCount;
  const mean_sm_2012 = stats2012.meanVal;
  const pixel_count_2012 = stats2012.pixelCount;

  // 4. Validation & Final Answer
  console.log(`2017 Images: ${size2017}`);
  console.log(`April 2017 SM (kg/m^2): ${mean_sm_2017 !== null ? mean_sm_2017.toFixed(2) : 'N/A'}, Pixels: ${pixel_count_2017}`);
  console.log(`2012 Images: ${size2012}`);
  console.log(`August 2012 SM (kg/m^2): ${mean_sm_2012 !== null ? mean_sm_2012.toFixed(2) : 'N/A'}, Pixels: ${pixel_count_2012}`);

  if (pixel_count_2017 === 0 || pixel_count_2012 === 0) {
    console.log("C2"); // No Valid Pixels after masking/reduction
    return;
  }

  if (mean_sm_2017 === null || isNaN(mean_sm_2017) || mean_sm_2012 === null || isNaN(mean_sm_2012)) {
    console.log("C3"); // Calculation Failure (None or NaN)
    return;
  }

  // Compare soil moisture
  if (mean_sm_2017 > mean_sm_2012) {
    console.log("A"); // Yes, soil moisture increased
  } else {
    console.log("B"); // No, soil moisture did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
